def closeness(pegs):
    ordered = sorted(pegs)
    distances = [
        abs(first[0] - second[0]) + abs(first[1] - second[1])
        for index, first in enumerate(ordered)
        for second in ordered[index + 1:]
    ]
    return min(distances) if distances else 0


def probe(env):
