                _, visible_bridges, visible_pegs, _ = parse_world(
                    scan.frame(), offset
                )
                world_bridges |= visible_bridges
                if scan_index == 0:
                    world_pegs = visible_pegs
                if scan_index < 14:
                    safe_step(scan, 4)
            print("world_load", index, cost, kind,
