        (blob.color, blob.top_left)
        for blob in connected_components(frame, colors=(9, 12, 14))
        if blob.size in ((2, 2), (4, 4))
    ))


def local_goals(frame, max_depth=10):
    blobs = connected_components(frame, colors=(1, 9, 12, 14, 15))
    holes = {
        blob.top_left for blob in blobs
        if blob.color == 1 and blob.size == (4, 4) and blob.area == 16
    }
    bridges = frozenset(
        blob.top_left for blob in blobs
        if blob.color == 9 and blob.size == (4, 4)
    )
    pegs = frozenset(
        blob.top_left for blob in blobs
        if blob.color == 14 and blob.size == (4, 4)
    )
    carriers = frozenset(
        blob.top_left for blob in blobs
        if blob.color == 12 and blob.size == (4, 4)
    )
    fixed = frozenset(
        (blob.bbox[0] + 1, blob.bbox[1]) for blob in blobs
        if blob.color == 15 and blob.size == (4, 4)
    )
    cells = holes | bridges | pegs | carriers | fixed
    start = (pegs, bridges)
    queue = deque([(start, ())])
    seen = {start}
    goals = []
    minimum = None
    while queue:
        (state_pegs, state_bridges), path = queue.popleft()
        if minimum is not None and len(path) >= minimum:
            continue
        occupied = state_pegs | state_bridges | fixed
        for kind, sources in (("P", state_pegs), ("B", state_bridges)):
            for source in sources:
                for dr, dc in ((-6, 0), (6, 0), (0, -6), (0, 6)):
                    midpoint = (source[0] + dr, source[1] + dc)
                    destination = (source[0] + 2 * dr,
                                   source[1] + 2 * dc)
                    if (
                        midpoint not in occupied
                        or destination not in cells
                        or destination in occupied
                    ):
                        continue
                    child_pegs = set(state_pegs)
                    child_bridges = set(state_bridges)
                    if kind == "P":
                        child_pegs.remove(source)
                        child_pegs.add(destination)
                        child_pegs.discard(midpoint)
                    else:
                        child_bridges.remove(source)
                        child_bridges.add(destination)
                    child = (frozenset(child_pegs),
                             frozenset(child_bridges))
                    child_path = path + ((kind, source, destination),)
                    progress = (
                        len(child[0]) < len(pegs)
                        or bool(child[0] & carriers)
                    )
                    if progress:
                        minimum = len(child_path)
                        goals.append(child_path)
                    elif len(child_path) < max_depth and child not in seen:
                        seen.add(child)
                        queue.append((child, child_path))
    return len(seen), minimum, tuple(goals)


