def rail_graph(frame, current_carrier):
    grid = arr(frame)
    positions = {
        (row, col)
        for row in range(6, 55, 6)
        for col in range(3, 58, 6)
        if ((grid[row:row + 4, col:col + 4] == 5).sum() >= 8
            or (row, col) == current_carrier)
    }

    def joined(first, second):
        if first[0] == second[0]:
            left = min(first[1], second[1])
            gap = grid[first[0]:first[0] + 4, left + 4:left + 6]
        else:
            top = min(first[0], second[0])
            gap = grid[top + 4:top + 6, first[1]:first[1] + 4]
        return (gap == 5).sum() >= 4 or (gap == 11).any()

    graph = {position: [] for position in positions}
    for position in positions:
        for action, (dr, dc) in (
            (1, (-6, 0)), (2, (6, 0)),
            (3, (0, -6)), (4, (0, 6)),
        ):
            child = (position[0] + dr, position[1] + dc)
            if child in positions and joined(position, child):
                graph[position].append((action, child))
    return graph


def shortest(graph, start, goal):
    queue = [(0, start, ())]
    seen = {start}
    while queue:
        cost, position, path = heappop(queue)
        if position == goal:
            return path
        for action, child in graph.get(position, ()):
            if child not in seen:
                seen.add(child)
                heappush(queue, (cost + 1, child, path + (action,)))
    return None


