import json
import sys

sys.path.insert(0, "/Users/sasha/gkm/arc/crack_lab")

import gkm_arena as arena

from legs import (
    _bridge_carrier_state,
    _movable_bridge_solution,
    solve_wrapped_bridge_carrier_peg_solitaire,
)
from perception import connected_components, safe_step
from probe_level_event_closures import generic_moves


class Recorder:
    def __init__(self, inner):
        self.inner = inner
        self.path = []

    def __getattr__(self, name):
        return getattr(self.inner, name)

    def clone(self):
        return self.inner.clone()

    def step(self, action, *coordinates):
        recorded = ((action,) + coordinates) if coordinates else action
        self.path.append(recorded)
        return self.inner.step(action, *coordinates)


def split(path):
    groups = []
    keys = []
    index = 0
    while index < len(path):
        if isinstance(path[index], int):
            keys.append(path[index])
            index += 1
        else:
            groups.append((tuple(keys), (path[index], path[index + 1])))
            keys = []
            index += 2
    return tuple(groups)


def play(node, actions):
    for action in actions:
        safe_step(node, action)


def pieces(frame):
    return tuple(sorted(
        (blob.color, blob.top_left)
        for blob in connected_components(frame, colors=(8, 12, 14))
        if blob.size in ((2, 2), (4, 4))
    ))


def probe(env):
    with open("checkpoint.json") as stream:
        campaign = json.load(stream)["final_path"]
    prior = int(env.levels_completed)
    entry = None
    for action in campaign:
        safe_step(env, tuple(action) if isinstance(action, list) else action)
        current = int(env.levels_completed)
        if prior < 5 <= current:
            entry = env.clone()
            break
        prior = current

    recorder = Recorder(entry.clone())
    solve_wrapped_bridge_carrier_peg_solitaire(recorder)
    groups = split(tuple(recorder.path))
    node = entry.clone()
    cost = 0
    for keys, clicks in groups[:22]:
        play(node, keys + clicks)
        cost += len(keys) + 2
    alternate = (
        7, 2, 4, 4, 1, 1, 1, 1,
        (6, 45, 19), (6, 33, 19),
    )
    play(node, alternate)
    cost += len(alternate)
    print(
        "l6_undo_branch",
        cost,
        "pieces",
        pieces(node.frame()),
        "state",
        _bridge_carrier_state(node.frame()),
        "moves",
        generic_moves(node.frame()),
        "local",
        _movable_bridge_solution(node.frame()),
        flush=True,
    )

    follow = node.clone()
    follow_cost = cost
    for name, move in (
        ("bridge_left", ((6, 39, 19), (6, 27, 19))),
        ("peg_left", ((6, 33, 19), (6, 21, 19))),
        ("bridge_left_2", ((6, 27, 19), (6, 15, 19))),
        ("peg_left_2", ((6, 21, 19), (6, 9, 19))),
        ("bridge_left_3", ((6, 15, 19), (6, 3, 19))),
    ):
        play(follow, move)
        follow_cost += 2
        print(
            "l6_undo_follow",
            name,
            follow_cost,
            "pieces",
            pieces(follow.frame()),
            "state",
            _bridge_carrier_state(follow.frame()),
            "moves",
            generic_moves(follow.frame()),
            "local",
            _movable_bridge_solution(follow.frame()),
            flush=True,
        )


arena.run_program("lf52", probe)
